# Task: Update OpenCode to Use MCP Tools (Phase 3.3)

## Objective
Integrate MCP metrics tools into metabob-opencode for automatic reporting and CLI commands.

## Implementation Steps

### 1. Create `{{opencodePath}}/packages/opencode/src/session/template-metrics.ts`

```typescript
import { MCPClient } from '../mcp/client'

export class TemplateMetrics {
  constructor(private mcp: MCPClient) {}

  async reportExecution(data: {
    activityId: string
    templateId: string
    success: boolean
    duration: number
    cost: number
    tokens: { input: number, output: number, cache: number }
    errors?: string[]
  }): Promise<void> {
    // Call MCP tool (NO direct API call)
    await this.mcp.callTool('metabob_report_execution', data)
  }

  async getMetrics(templateId: string) {
    return await this.mcp.callTool('metabob_get_template_metrics', {
      template_id: templateId
    })
  }

  async getRecommendation(candidateId: string) {
    return await this.mcp.callTool('metabob_get_promotion_recommendation', {
      candidate_id: candidateId
    })
  }

  async promote(candidateId: string, reason: string) {
    return await this.mcp.callTool('metabob_promote_template', {
      candidate_id: candidateId,
      reason
    })
  }
}
```

### 2. Update `{{opencodePath}}/packages/opencode/src/session/activity.ts`

Add metrics reporting:

```typescript
import { TemplateMetrics } from './template-metrics'

export class Activity {
  private metrics: TemplateMetrics

  async execute() {
    const startTime = Date.now()
    let success = false
    const errors: string[] = []

    try {
      // Execute activity tasks...
      success = true
    } catch (error) {
      errors.push(error.message)
      throw error
    } finally {
      // ALWAYS report metrics (success or failure)
      await this.metrics.reportExecution({
        activityId: this.id,
        templateId: this.templateId,
        success,
        duration: (Date.now() - startTime) / 1000,
        cost: this.calculateCost(),
        tokens: this.getTokenUsage(),
        errors
      })
    }
  }
}
```

### 3. Add CLI Commands

**File: `{{opencodePath}}/packages/opencode/src/cli/commands/template.ts`**

```typescript
// opencode template metrics <id>
command
  .command('metrics <template-id>')
  .description('View template metrics')
  .action(async (templateId) => {
    const metrics = await templateMetrics.getMetrics(templateId)
    console.log(`Template: ${templateId}`)
    console.log(`Executions: ${metrics.executions}`)
    console.log(`Success Rate: ${(metrics.success_rate * 100).toFixed(1)}%`)
    console.log(`Avg Cost: $${metrics.avg_cost.toFixed(4)}`)
    console.log(`Avg Duration: ${metrics.avg_duration.toFixed(1)}s`)
  })

// opencode template promote <candidate-id>
command
  .command('promote <candidate-id>')
  .description('Promote candidate template to stable')
  .action(async (candidateId) => {
    const rec = await templateMetrics.getRecommendation(candidateId)

    if (rec.should_promote) {
      console.log(`✅ Recommendation: PROMOTE (confidence: ${rec.confidence})`)  
      console.log(rec.reason)

      const confirmed = await promptConfirm('Proceed with promotion?')
      if (confirmed) {
        await templateMetrics.promote(candidateId, 'Manual promotion via CLI')
        console.log('✅ Template promoted')
      }
    } else {
      console.log(`❌ Recommendation: DO NOT PROMOTE`)
      console.log(rec.reason)
    }
  })
```

